class Solution:
    def rotateRight(self, slots: List[int], k: int) -> List[int]:
        n = len(slots)
        for _ in range(k % n):
            last = slots[-1]
            for i in range(n - 1, 0, -1):
                slots[i] = slots[i - 1]
            slots[0] = last
        return slots

