class Solution {
    public int[] rotateRight(int[] slots, int k) {
        int n = slots.length;
        for (int t = 0; t < k % n; t++) {
            int last = slots[n - 1];
            for (int i = n - 1; i > 0; i--) slots[i] = slots[i - 1];
            slots[0] = last;
        }
        return slots;
    }
}

