class Solution:
    def rotateRight(self, slots: List[int], k: int) -> List[int]:
        n = len(slots)
        k %= n
        def rev(i, j):
            while i < j:
                slots[i], slots[j] = slots[j], slots[i]
                i, j = i + 1, j - 1
        rev(0, n - 1)
        rev(0, k - 1)
        rev(k, n - 1)
        return slots

