class Solution {
    public int[] rotateRight(int[] slots, int k) {
        int n = slots.length;
        k %= n;
        reverse(slots, 0, n - 1);
        reverse(slots, 0, k - 1);
        reverse(slots, k, n - 1);
        return slots;
    }

    private void reverse(int[] a, int i, int j) {
        for (; i < j; i++, j--) { int t = a[i]; a[i] = a[j]; a[j] = t; }
    }
}

